export const clamp=(v,min,max)=>Math.min(max,Math.max(min,Number.isFinite(v)?v:min));
const lerp=(a,b,t)=>a+(b-a)*clamp(t,0,1);
export const DURATION=30;
export const stages=[{start:0,end:2,name:'怠速等候'},{start:2,end:5,name:'1 檔起步'},{start:5,end:5.5,name:'升 2 檔'},{start:5.5,end:8,name:'2 檔加速'},{start:8,end:8.5,name:'升 3 檔'},{start:8.5,end:11,name:'3 檔加速'},{start:11,end:11.5,name:'升 4 檔'},{start:11.5,end:21.5,name:'恆速巡航'},{start:21.5,end:26.5,name:'煞車減速'},{start:26.5,end:30,name:'停車怠速'}];
function originalCycle(seconds){const t=clamp(seconds,0,30),i=Math.max(0,stages.findIndex(s=>t<s.end)),index=t===30?9:i,s=stages[index],u=(t-s.start)/(s.end-s.start);let rpm=780,speed=0,gear=1,load=.16,brake=0;
switch(index){case 0:rpm=780+8*Math.sin(t*3);break;case 1:rpm=lerp(780,1600,u);speed=12*u;load=.8;break;case 2:rpm=lerp(1600,1150,u);speed=12;gear=2;load=.28;break;case 3:rpm=lerp(1150,1650,u);speed=lerp(12,25,u);gear=2;load=.8;break;case 4:rpm=lerp(1650,1200,u);speed=25;gear=3;load=.28;break;case 5:rpm=lerp(1200,1600,u);speed=lerp(25,40,u);gear=3;load=.75;break;case 6:rpm=lerp(1600,1150,u);speed=40;gear=4;load=.25;break;case 7:rpm=1175-25*Math.cos(u*Math.PI*4);speed=40;gear=4;load=.36;break;case 8:{speed=40*(1-u);gear=speed>28?4:speed>15?3:speed>5?2:1;const phase=u<.3?u/.3:u<.65?(u-.3)/.35:(u-.65)/.35;rpm=lerp(u<.3?1150:1400,u<.3?1400:1000,phase);load=.12;brake=.85;break;}case 9:rpm=t<28?lerp(1000,780,(t-26.5)/1.5):780;speed=0;gear=1;break;}
return{time:t,stage:index,phase:s.name,rpm,speed,gear,load,brake,frequency:rpm/20,retarder:false,done:t>=30};}
export function manualStep(state,controls,dt){dt=clamp(dt,0,.1);const gas=clamp(controls.throttle,0,1),brake=clamp(controls.brake,0,1),base=clamp(controls.rpm,600,2400);const speed=clamp(state.speed+(gas*5.4-brake*13.5-(state.speed>.01?.35:0))*dt,0,80);const automatic=speed<12?1:speed<25?2:speed<40?3:speed<52?4:speed<65?5:6,forced=Number.isInteger(controls.gear)&&controls.gear>=1&&controls.gear<=6,gear=forced?controls.gear:automatic;const target=brake>.05&&speed>1?1000+400*((speed%12)/12):clamp(forced&&speed>1?base+speed*70/gear+gas*400:base+gas*1150,600,2400);const rpm=lerp(state.rpm,target,1-Math.exp(-dt*4));return{time:0,stage:-1,phase:brake>.05?'手動煞車':gas>.05?'手動加速':'手動怠速',rpm,speed,gear,load:.16+gas*.7,brake,frequency:rpm/20,retarder:brake>.05&&speed>.5,done:false};}
export function soundValues(state,condition='normal'){const rpm=clamp(state.rpm,600,2400),speed=clamp(state.speed,0,80),v={good:.6,normal:1,poor:1.7}[condition]||1;return{frequency:rpm/20,bodyFrequency:rpm/10,combustion:.19+clamp(state.load,0,1)*.12,body:.075*v,clatter:(.042+clamp(state.load,0,1)*.048)*v,whineFrequency:450+Math.min(speed,40)/40*300,whineGain:state.retarder?.045*clamp(speed/8,0,1):0};}

export const drivingStyles={standard:{accel:1,brake:1,peak:1650,drop:1150,load:.8},aggressive:{accel:1.4,brake:1.25,peak:2150,drop:1450,load:1},relaxed:{accel:.72,brake:.8,peak:1400,drop:1000,load:.5}};
export function routePlan(target=40,style='standard'){target=[20,30,40,50,60].includes(Number(target))?Number(target):40;style=Object.hasOwn(drivingStyles,style)?style:'standard';const p=drivingStyles[style],accel=9.5*target/40/p.accel,braking=5*target/40/p.brake,cruiseStart=2+accel,brakeStart=cruiseStart+10,stopStart=brakeStart+braking,total=stopStart+3.5;return{target,style,...p,accel,braking,cruiseStart,brakeStart,stopStart,total};}
export function cycleState(seconds,options={}){const plan=routePlan(options.target,options.style);if(plan.target===40&&plan.style==='standard')return{...originalCycle(seconds),duration:30};const t=clamp(seconds,0,plan.total);let rpm=780,speed=0,gear=1,load=.16,brake=0,phase='怠速等候';if(t<2){rpm=780+8*Math.sin(t*3);}else if(t<plan.cruiseStart){const thresholds=[12,25,40,52,65].filter(v=>v<=plan.target),shiftTime=.5/drivingStyles[plan.style].accel,driveTime=plan.accel-thresholds.length*shiftTime;let cursor=2,fromSpeed=0,startRpm=780;for(const toSpeed of [...thresholds,...(thresholds.at(-1)===plan.target?[]:[plan.target])]){const end=cursor+driveTime*(toSpeed-fromSpeed)/plan.target;if(t<end){speed=lerp(fromSpeed,toSpeed,(t-cursor)/(end-cursor));rpm=lerp(startRpm,plan.peak,(t-cursor)/(end-cursor));phase=gear+' 檔加速';load=plan.load;break;}speed=toSpeed;rpm=plan.peak;cursor=end;if(thresholds.includes(toSpeed)){if(t<cursor+shiftTime){rpm=lerp(plan.peak,plan.drop,(t-cursor)/shiftTime);gear++;phase='升 '+gear+' 檔';load=.25;break;}cursor+=shiftTime;gear++;startRpm=plan.drop;}fromSpeed=toSpeed;}}else if(t<plan.brakeStart){speed=plan.target;gear=1+[12,25,40,52,65].filter(v=>v<=plan.target).length;rpm=plan.drop+25-25*Math.cos((t-plan.cruiseStart)/10*Math.PI*4);phase='恆速巡航';load=plan.load*.45;}else if(t<plan.stopStart){const u=(t-plan.brakeStart)/plan.braking;speed=plan.target*(1-u);gear=1+[12,25,40,52,65].filter(v=>v<speed).length;rpm=1000+400*Math.abs(Math.sin(u*Math.PI*3));phase='煞車減速';brake=.85;load=.12;}else{rpm=lerp(1000,780,(t-plan.stopStart)/1.5);phase='停車怠速';}return{time:t,stage:t<2?0:t<plan.cruiseStart?1:t<plan.brakeStart?7:t<plan.stopStart?8:9,phase,rpm,speed,gear,load,brake,frequency:rpm/20,retarder:false,done:t>=plan.total,duration:plan.total};}
